# ---------- reference FIRST/FOLLOW/LL(1) table with conflict detection ----------
def ref_tables(rules, start):
    NT=set(rules)
    FIRST={A:set() for A in NT}
    def fstr(seq):
        out=set(); nullable=True
        for c in seq:
            if c=='@': continue
